SET @s := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND LOWER(TABLE_NAME)='joomla_vigling_user_courses' AND COLUMN_NAME='is_online')=0, 'ALTER TABLE `joomla_vigling_user_courses` ADD COLUMN `is_online` TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER `booking_mode`', 'SELECT ''is_online already present''');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND LOWER(TABLE_NAME)='joomla_vigling_user_courses' AND COLUMN_NAME='online_url')=0, 'ALTER TABLE `joomla_vigling_user_courses` ADD COLUMN `online_url` VARCHAR(2048) NULL AFTER `is_online`', 'SELECT ''online_url already present''');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
CREATE TABLE IF NOT EXISTS `joomla_vigling_course_search_links` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `course_id` INT UNSIGNED NOT NULL, `part_no` TINYINT UNSIGNED NOT NULL DEFAULT 1, `search_id` INT UNSIGNED NOT NULL, `search_slot_id` INT UNSIGNED NULL, PRIMARY KEY (`id`), UNIQUE KEY `uniq_course_search_part` (`course_id`, `part_no`), KEY `idx_course_search_offer` (`search_id`, `search_slot_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SELECT 'done: course online and linked searches' AS check_name, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND LOWER(TABLE_NAME)='joomla_vigling_user_courses' AND COLUMN_NAME IN ('is_online','online_url')) AS course_columns, (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND LOWER(TABLE_NAME)='joomla_vigling_course_search_links') AS link_table;
